BEGIN;
CREATE TEMP TABLE scalar_null_sections(id NUMERIC(10) PRIMARY KEY,scope_id NUMERIC(10),active CHAR(1));
CREATE TEMP TABLE scalar_null_fields(id NUMERIC(10) PRIMARY KEY,section_id NUMERIC(10),active CHAR(1),hidden VARCHAR(1));
CREATE UNIQUE INDEX ON scalar_null_fields(section_id,id) NULLS NOT DISTINCT;
CREATE TEMP TABLE scalar_null_seen(id NUMERIC(10),scope_id NUMERIC(10));
CREATE TEMP TABLE scalar_null_visible(id NUMERIC(10),scope_id NUMERIC(10));
INSERT INTO scalar_null_sections VALUES(3,7,'Y'),(9,7,'Y'),(1,8,'Y');
INSERT INTO scalar_null_fields SELECT i,(i-1)%100+1,'Y',NULL FROM generate_series(1,5000)i;
ANALYZE scalar_null_fields;
SELECT jsonb_build_object('version',current_setting('server_version'),'nonnull_rows',(SELECT count(*) FROM (SELECT id FROM scalar_null_fields WHERE active='Y' AND section_id=(SELECT min(id) FROM scalar_null_sections WHERE scope_id=7 AND active='Y') AND hidden IS NULL AND id NOT IN(SELECT id FROM scalar_null_seen WHERE scope_id=11 AND id IS NOT NULL) AND (id IN(SELECT id FROM scalar_null_visible WHERE scope_id=11) OR (SELECT count(*) FROM scalar_null_visible WHERE scope_id=11)=0) ORDER BY coalesce(active,'Y') DESC,id)s),'null_aggregate_rows',(SELECT count(*) FROM (SELECT id FROM scalar_null_fields WHERE active='Y' AND section_id=(SELECT min(id) FROM scalar_null_sections WHERE scope_id=404 AND active='Y') AND hidden IS NULL AND id NOT IN(SELECT id FROM scalar_null_seen WHERE scope_id=11 AND id IS NOT NULL) AND (id IN(SELECT id FROM scalar_null_visible WHERE scope_id=11) OR (SELECT count(*) FROM scalar_null_visible WHERE scope_id=11)=0) ORDER BY coalesce(active,'Y') DESC,id)s),'null_projection_rows',(SELECT count(*) FROM scalar_null_fields WHERE section_id=(SELECT CAST(NULL AS NUMERIC))));
EXPLAIN(ANALYZE,FORMAT JSON) SELECT id FROM scalar_null_fields WHERE active='Y' AND section_id=(SELECT min(id) FROM scalar_null_sections WHERE scope_id=404 AND active='Y') AND hidden IS NULL AND id NOT IN(SELECT id FROM scalar_null_seen WHERE scope_id=11 AND id IS NOT NULL) AND (id IN(SELECT id FROM scalar_null_visible WHERE scope_id=11) OR (SELECT count(*) FROM scalar_null_visible WHERE scope_id=11)=0) ORDER BY coalesce(active,'Y') DESC,id;
ROLLBACK;

