BEGIN;
CREATE TEMP TABLE outer_choices(id INT PRIMARY KEY,wanted INT);
CREATE TEMP TABLE target_matches(id INT PRIMARY KEY,lookup_key INT);
CREATE INDEX ON target_matches(lookup_key);
INSERT INTO outer_choices VALUES(1,NULL),(2,2),(3,3);
INSERT INTO target_matches VALUES(10,2),(11,3);
SELECT jsonb_agg(jsonb_build_array(id,matched) ORDER BY id) FROM (SELECT o.id,t.id AS matched FROM outer_choices o LEFT JOIN target_matches t ON t.lookup_key=(SELECT o.wanted))s;
SELECT jsonb_agg(jsonb_build_array(id,matched) ORDER BY id) FROM (SELECT o.id,t.id AS matched FROM outer_choices o LEFT JOIN LATERAL (SELECT r.id FROM target_matches r WHERE r.lookup_key=(SELECT o.wanted))t ON TRUE)s;
ROLLBACK;
